python
def tallerKeycapsBossReceipt(readings):
    a=readings
    out=[]
    out=[0]*len(a)
    stack=[]
    for i,x in enumerate(a):
        while stack and a[stack[-1]]<x:
            j=stack.pop()
            out[j]=i-j
        stack.append(i)
    return sum((i+1)*x for i,x in enumerate(out))


java
class Solution {
  public int tallerKeycapsBossReceipt(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]distance=new int[a.length];Deque<Integer>stack=new ArrayDeque<>();for(int i=0;i<a.length;i++){while(!stack.isEmpty()&&a[stack.peek()]<a[i]){int j=stack.pop();distance[j]=i-j;}stack.push(i);}for(int x:distance)out.add(x);}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
